  // Guided Recovery tab (disaster-recovery walkthrough)
  "recovery.intro": "Khôi phục các container và VMs của bạn từ một bản sao lưu hiện có vào bản cài đặt này.",
  "recovery.step1": "BombVault có đọc được các bản sao lưu của bạn không?",
  "recovery.appKeyExplain": "Để đọc các bản sao lưu hiện có, container này cần ĐÚNG APP_KEY mà nó đã dùng trước đây. Nó nằm trong bộ khôi phục của bạn. Hãy đặt nó trong container template của Unraid nếu chưa đặt, rồi kiểm tra lại.",
  "recovery.appKeyRemedy": "Khóa mã hóa không khớp với các bản sao lưu này. Hãy đặt APP_KEY gốc (từ bộ khôi phục của bạn) trong container template, rồi kiểm tra lại.",
  "recovery.readable": "Các bản sao lưu của bạn đọc được.",
  "recovery.readFrom": "Đọc từ:",
  "recovery.notReachable": "Chưa thể truy cập các bản sao lưu của bạn. Đính kèm vị trí bên dưới, rồi kiểm tra lại.",
  "recovery.recheck": "Kiểm tra",
  "recovery.step2": "Đính kèm các bản sao lưu của bạn",
  "recovery.attachHint": "Trỏ BombVault tới các bản sao lưu hiện có của bạn. Trên hàng của mỗi miền, chọn điểm lưu trữ chứa các bản sao lưu của miền đó ở “Lưu tại”, và các điểm lưu trữ giữ bản sao của nó ở “Sao chép đến”. Một điểm lưu trữ chưa có hàng nào đưa ra, chẳng hạn một thư mục chia sẻ, một máy chủ hay một bucket đám mây, được kết nối bằng “Thêm điểm lưu trữ”.",
  "recovery.credsSaveHint": "Một điểm lưu trữ mới và mọi lựa chọn trên một hàng đều được lưu ngay. Sau đó “Kết nối và xem trước” kiểm tra xem các bản sao lưu có đọc được không.",
  "recovery.connectPreview": "Kết nối và xem trước",
  "recovery.encChecking": "Đang kiểm tra bản sao lưu của bạn được mã hoá thế nào…",
  "recovery.encEncrypted": "Đã phát hiện: bản sao lưu của bạn được mã hoá. BombVault sẽ dùng mật khẩu suy ra từ APP_KEY của bạn.",
  "recovery.encPlain": "Đã phát hiện: bản sao lưu của bạn không có mật khẩu.",
  "recovery.encAbsent": "Chưa có kho sao lưu nào ở các vị trí này nên không có gì để phát hiện. Lựa chọn bên dưới của bạn quyết định nó sẽ được tạo ra sao.",
  "recovery.encUnknown": "Chưa thể xác định: không mở được các kho, nên chế độ mã hoá của chúng là chưa rõ. Hãy sửa vị trí ở trên rồi kiểm tra lại, hoặc tự đặt nếu bạn đã biết.",
  "recovery.encConflict": "Các kho của bạn mâu thuẫn nhau: một số được mã hoá, một số thì không. Một thiết lập không thể mở cả hai. Hãy trỏ cái lệch sang một vị trí mới, trống, hoặc chỉ khôi phục từ nhóm khớp nhau.",
  "recovery.encUnconfigured": "Chưa cấu hình vị trí sao lưu nào. Hãy chọn nơi chứa bản sao lưu của từng miền ở “Lưu tại” trên các hàng bên dưới, hoặc kết nối điểm lưu trữ của chúng bằng “Thêm điểm lưu trữ”, rồi dùng “Kết nối và xem trước”.",
  "recovery.encDetectHint": "Mã hoá không phải là tuỳ chọn sở thích: một kho được tạo ra hoặc có mật khẩu (suy ra từ APP_KEY của bạn) hoặc không, và điều đó không bao giờ thay đổi về sau. BombVault mở các kho đã cấu hình để xem thuộc trường hợp nào, nên khôi phục trên máy mới không cần đoán. Kho không truy cập được sẽ báo là chưa rõ, không bao giờ báo là không mã hoá.",
  "recovery.encStateEncrypted": "đã mã hoá",
  "recovery.encStatePlain": "không mật khẩu",
  "recovery.encStateAbsent": "chưa được tạo",
