  // Recovery — restore BombVault's own settings (config)
  "recovery.stepConfig": "Khôi phục cài đặt của chính BombVault",
  "recovery.configHint": "Trên một máy chủ dựng lại, hãy khôi phục cài đặt của chính BombVault trước (đường dẫn sao lưu, đích off-site và thông tin đăng nhập) để các bước bên dưới được điền sẵn. Bản sao lưu cài đặt được đọc từ điểm lưu trữ hiển thị ở đây, do hàng “Tự sao lưu” ở bước 3 quyết định. Không có bản sao lưu cài đặt? Bỏ qua bước này và đính kèm các bản sao lưu của bạn thủ công bên dưới.",
  "recovery.configAppKeyReminder": "APP_KEY của bạn phải khớp với bản sao lưu này. Đó là bước kiểm tra ở Bước 1 phía trên.",
  "recovery.configSourceLabel": "Bản sao lưu cài đặt ở đâu?",
  "recovery.configOtherHome": "Để khôi phục từ một điểm lưu trữ khác, hãy chọn nó ở “Lưu tại” trên hàng “Tự sao lưu” ở bước 3.",
