  "recovery.configNoCopy": "Tự sao lưu chưa có bản sao nào. Để khôi phục từ một bản sao, hãy thêm điểm lưu trữ của nó vào “Sao chép đến” trên hàng “Tự sao lưu” ở bước 3.",
  "recovery.configRestore": "Khôi phục",
