  "dbdump.import": "Nhập vào cơ sở dữ liệu mới",
  "dbdump.importConfirm": "Nhập bản kết xuất {engine} {version} này vào {container}? BombVault dừng vùng chứa, đưa thư mục dữ liệu của nó sang một bên (vẫn được giữ, không xóa gì cả), khởi động vùng chứa với thư mục dữ liệu trống rồi nhập bản kết xuất. Các ứng dụng dùng cơ sở dữ liệu này sẽ thấy trạng thái của nó tại thời điểm kết xuất.",
  "dbdump.importConfirmNoVersion": "Nhập bản kết xuất {engine} này vào {container}? BombVault dừng vùng chứa, đưa thư mục dữ liệu của nó sang một bên (vẫn được giữ, không xóa gì cả), khởi động vùng chứa với thư mục dữ liệu trống rồi nhập bản kết xuất. Các ứng dụng dùng cơ sở dữ liệu này sẽ thấy trạng thái của nó tại thời điểm kết xuất.",
  "dbdump.importNoVersion": "Bản kết xuất này không ghi lại phiên bản cơ sở dữ liệu. Việc nhập sẽ thất bại nếu máy chủ không đọc được nó.",
  "dbdump.importStops": "Trong lúc nhập, BombVault cũng dừng các ứng dụng sau: {apps}. Sau đó sẽ khởi động lại. Nếu việc nhập thất bại sau khi đã bắt đầu, dữ liệu cũ vẫn nằm ở chỗ khác và các ứng dụng vẫn dừng.",
  "dbdump.importDone": "Đã nhập cơ sở dữ liệu.",
  "dbdump.importRefused.busy": "Đang có một lần sao lưu hoặc khôi phục khác chạy. Hãy thử lại khi nó xong.",
  "dbdump.importRefused.notRunning": "Hãy khởi động vùng chứa trước; việc nhập cần máy chủ đang chạy.",
  "dbdump.importRefused.engineMismatch": "Bản kết xuất này đến từ loại cơ sở dữ liệu khác với loại vùng chứa đang chạy.",
  "dbdump.importRefused.noDataMount": "BombVault không với tới thư mục dữ liệu của vùng chứa này nên không thể đưa nó sang một bên an toàn. Hãy nhập bản kết xuất bằng tay như bộ công cụ khôi phục mô tả.",
  "dbdump.importRefused.version": "Máy chủ chạy phiên bản {server}, bản kết xuất đến từ {dump}. Hãy dùng ảnh có phiên bản {dump} trở lên cho lần nhập này.",
  "dbdump.importRefused.versionSameMajor": "Máy chủ chạy phiên bản {server}, bản kết xuất đến từ {dump}. MySQL và MariaDB chỉ nhập bản kết xuất vào đúng phiên bản lớn mà nó được lấy ra, nên hãy dùng ảnh có phiên bản {dump} cho lần nhập này.",
  "dbdump.importRefused.damaged": "Bản kết xuất này bị hỏng và không nhập được.",
  "dbdump.importRefused.notADump": "Ảnh chụp này không phải là bản kết xuất cơ sở dữ liệu của vùng chứa này.",
  "dbdump.restoreLiveWarn": "Các tệp của cơ sở dữ liệu này được chép khi máy chủ đang chạy, nên các tệp khôi phục có thể không khởi động sạch sẽ. Nếu vậy, hãy nhập bản kết xuất lấy cùng lần sao lưu này, nằm trong danh sách bên dưới.",
  "dbdump.restoreNoneWarn": "Thư mục dữ liệu của cơ sở dữ liệu này không có trong bản sao lưu. Khôi phục sẽ mang vùng chứa trở lại với cơ sở dữ liệu trống; sau đó hãy nhập một bản kết xuất từ danh sách bên dưới.",
  "dbdump.deleteConfirm": "Xóa bản kết xuất cơ sở dữ liệu này? Nó sẽ bị gỡ khỏi kho (chạy Prune trong Cài đặt để lấy lại dung lượng). Việc này không thể hoàn tác.",
  "dbdump.pairedBadge": "Có bản kết xuất cơ sở dữ liệu",
