  "places.intro.s3Cloud": "Một khóa truy cập lấy từ bảng điều khiển của nhà cung cấp. BombVault liệt kê các bucket mà khóa được phép thấy.",
  "places.intro.gcs": "Một khóa HMAC cho giao diện S3 của Cloud Storage, lấy từ phần cài đặt Interoperability của bucket.",
  "places.intro.azure": "Tài khoản lưu trữ, một trong các khóa truy cập của tài khoản đó và container để ghi vào.",
  "places.intro.storagebox": "Thêm khóa công khai của BombVault vào Storage Box, rồi nhập người dùng của Storage Box. BombVault kết nối qua cổng 23.",
  "places.intro.s3Self": "Địa chỉ dịch vụ S3 của bạn và một khóa cho dịch vụ đó. BombVault liệt kê các bucket mà khóa được phép thấy.",
  "places.intro.webdav": "BombVault ghi qua WebDAV. Hãy tạo một mật khẩu ứng dụng cho BombVault, để nó không bao giờ cần mật khẩu thật của bạn.",
  "places.intro.rest": "Một rest-server của restic. Khi khởi động với --private-repos, nó chỉ phục vụ mỗi người dùng đường dẫn riêng của họ, và BombVault đặt đường dẫn đó lên đầu. Với --append-only, không gì ở đây có thể xóa một bản sao lưu ở đó.",
  "places.intro.sftp": "Bất kỳ máy nào có SSH. Thêm khóa công khai của BombVault vào authorized_keys của người dùng.",
  "places.intro.bombvault": "rest-server mà một BombVault khác chạy cho bạn: địa chỉ, người dùng và mật khẩu của nó.",
  "places.intro.rclone": "Một remote trong cấu hình rclone của BombVault.",
  "places.intro.device": "Trước tiên hãy gắn kết chia sẻ trong Unraid, ví dụ bằng Unassigned Devices. Sau đó chọn một thư mục trên chia sẻ đó tại đây.",
  "places.intro.unraidFolder": "Một thư mục khác trên máy chủ này, ví dụ trên một ổ đĩa riêng.",
