  "places.details.isRepository": "Điểm lưu trữ này tự nó là một kho: mọi miền được cung cấp ở đây dùng chung kho này, và bên dưới không có thư mục nào. Để lưu thêm ở đây, hãy kết nối một bucket hoặc thư mục thứ hai thành một điểm lưu trữ riêng.",
