  "anomaly.title": "Bất thường",
  "anomaly.cardHint": "BombVault so sánh từng bản sao lưu của một mục với các bản trước và nêu tên những gì không khớp: dữ liệu mới nhiều hơn thường lệ rất nhiều, phần lớn dữ liệu bị ghi lại, nguồn thu nhỏ hoặc phình to đột ngột, bản kết xuất cơ sở dữ liệu nhỏ đi, bản sao lưu bỗng kéo dài hơn hẳn, các lần thất bại lặp lại, một lần kiểm tra khôi phục không còn đạt, và một ổ đĩa sắp đầy. Hầu hết các phép kiểm tra cần 10 bản sao lưu của mục đó trước đã. Một mục ZFS được kiểm tra theo từng tập dữ liệu, nên một tập dữ liệu con bị làm trống vẫn hiện ra kể cả trong một cây lớn.",
